library_mount_modal_usb_warn_body: "/mnt/usb*와 /mnt/ext*는 PS5 커널의 USB 핫플러그 네임스페이스에 속하며, 대부분의 펌웨어에서 커널 정책상 그곳에 이미지를 마운트하는 것이 차단됩니다. \"Operation not permitted\"로 실패하면 /mnt/ps5upload(페이로드 전용 마운트 루트) 또는 /data로 바꾸세요 — 둘 다 커널 패치 없이 동작합니다.",
