  queue_phase_finalizing: "PS5에서 마무리 중",
  queue_phase_finalizing_hint: "모든 바이트가 PS5에 전송되었고 파일 색인을 커밋하는 중입니다. 파일 수가 많으면(1만 개 이상) 이 단계에서 몇 분씩 걸리는 것이 보통입니다 — 앱을 닫지 마세요.",
  upload_status_finalizing: "PS5에서 마무리 중",
  upload_status_finalizing_hint: "PS5가 파일 색인을 커밋하는 중입니다. 파일 수가 많으면 시간이 걸릴 수 있습니다 — 앱을 닫지 마세요.",
  upload_file_list_windowed: "{shown} 표시 중",
  upload_file_list_windowed_hint: "현재 파일 주변만 표시합니다. 5만 개가 넘는 폴더의 모든 항목을 그리면 앱이 멈춥니다.",
  upload_eta_simplified: "예상 업로드 시간: {eta}",
  upload_eta_default_qualifier: "추정치 — 이 PS5로의 첫 업로드",
  upload_eta_banner_title: "용량이 큰 폴더 업로드입니다.",
