  upload_eta_row_transfer: "전송",
  upload_eta_row_commit: "PS5 반영",
  upload_eta_row_total: "합계",
  upload_eta_resume_hint: "이 정도 크기의 폴더에서는 이어서 업로드 모드(PS5에 이미 있는 파일 건너뛰기)를 쓰면 반복 업로드에서 한 시간 이상 절약됩니다. 업로드를 클릭하면 선택지가 나타납니다.",
  activity_phase_finalizing_with_counter: "PS5에서 마무리 중 — {done} / {total}개 파일",
  upload_status_finalizing_counter: "{done} / {total}개 파일을 마무리했습니다. ",
  queue_phase_finalizing_with_counter: "PS5에서 마무리 중 — {done} / {total}",
  upload_scanning_title: "게임 폴더 검사 중…",
  upload_scanning_hint: "파일 수를 세고 업로드 계획을 세우는 중입니다. 큰 폴더(10만 개 이상)는 30초 정도 걸립니다. 완료되면 업로드 버튼이 활성화됩니다.",
  upload_scanning_archive_title: "아카이브 검사 중…",
  upload_scanning_archive_title_with_count: "아카이브 검사 중… 항목 {count}개",
  upload_scanning_archive_hint: "'.zip'의 중앙 디렉터리를 읽고 내장된 게임 메타데이터를 분석하는 중입니다. 완료되면 업로드 버튼이 활성화됩니다.",
  upload_disabled_scanning: "게임 폴더를 검사하는 중입니다 — 검사가 끝나면 이 버튼이 활성화됩니다.",
