installed_kstuff_off_body: "페이로드에 커널 읽기/쓰기 권한이 없어 jailbreak/kstuff 진입점이 로드되지 않았습니다. kstuff를 통해 콘솔을 로드하고 다시 연결할 때까지 fpkg 게임 실행(및 설치)은 실패합니다.",
