installed_hide_confirm_body: "아이콘만 숨겨집니다. 설치와 저장 데이터는 그대로이며 여기서 계속 실행할 수 있습니다. 이 메뉴에서 다시 표시하세요. PS5 홈 화면은 다음에 아무 앱이나 열었다 닫을 때 갱신됩니다.",
