  upload_auto_resume_hint:
    "업로드가 전송 도중 끊어지면 — 대부분 PS5 페이로드 크래시가 원인 — 페이로드를 자동으로 다시 보내고 중단된 지점부터 재개하며, 포기하기 전에 몇 차례 재시도합니다. PS5 공간 부족 같은 치명적인 문제는 여전히 즉시 중단됩니다. 기본적으로 켜져 있습니다.",
