backup_snapshot_ok: "{files}개 파일을 스냅샷했습니다({bytes})",
backup_warning: "스냅샷은 PS5의 /data/ps5upload/backups/ 에 저장됩니다. 복원하면 원래 경로의 기존 파일을 덮어씁니다.",
bringup_chain_with: "{name} → 헬퍼 → 자동 로더",
bringup_failed: "{phase} 단계에서 구동 실패: {error}",
bringup_phase_prehelper: "초기 구동 페이로드를 불러오는 중({name})…",
engine_url_hint: "앱이 ps5upload-engine에 접속하는 위치입니다. 기본 로컬 sidecar를 그대로 두거나 원격/자체 호스팅 엔진을 지정하세요. 로컬과 원격을 전환한 뒤에는 앱을 다시 시작하세요.",
err_fs_read_path_not_allowed: "이 파일은 보통 차단되는 읽기 전용 시스템 파티션에 있습니다. 설정 → “시스템 파일 다운로드 허용”을 켜면 /system, /system_data 등 보호된 경로에서 읽을 수 있습니다. 다운로드에만 적용되며, 그곳에서 삭제·이동·쓰기는 절대 허용되지 않습니다.",
err_rar_open_failed: "이 RAR 파일을 읽을 수 없습니다. 분할 압축이라면 첫 번째 파일(…part1.rar / …part01.rar / ….rar)을 선택하고 모든 분할 파일이 같은 폴더에 있는지 확인하세요. 비밀번호가 걸려 있다면 비밀번호를 입력하세요.",
err_rar_password_required: "이 RAR 파일은 비밀번호로 보호되어 있습니다. 내용을 읽고 업로드하려면 아래에 비밀번호를 입력하세요.",
err_rar_unsafe_entry: "이 RAR에는 대상 폴더 밖을 가리키는 파일 경로가 있어 안전을 위해 거부되었습니다. 파일이 손상되었을 수 있습니다.",
err_rar_unsupported: "이 빌드에서는 RAR을 지원하지 않습니다(안드로이드는 .zip과 .7z만 업로드). 먼저 컴퓨터에서 .rar을 풀거나 데스크톱 앱을 사용하세요.",
fs_download_zip_dialog_title: "“{name}”을(를) .zip으로 저장",
fs_install_confirm_body_usb: "패키지를 내부 저장소에 임시로 올린 뒤(콘솔은 USB에서 바로 설치할 수 없습니다) 설치하고, 임시 사본을 지웁니다. 드라이브의 원본은 그대로 둡니다.",
