fs_path_gone_body: "{path}은(는) 더 이상 PS5에 없습니다.",
fs_rename_target_exists: "여기에 “{name}”이라는 항목이 이미 있습니다. 이름을 바꾸면 덮어쓰게 됩니다. 다른 이름을 쓰거나 먼저 삭제하세요.",
fw_spoof_kernel_unknown_warn: "커널 버전을 읽지 못했습니다. 위조 감지가 정확하지 않을 수 있습니다.",
game_hub_launch_unconfirmed_body: "PS5가 실행 요청을 받아들였지만 타이틀이 아직 나타나지 않았습니다. 콘솔을 확인하세요. 아직 시작 중일 수 있습니다.",
