library_show_all: "{count}개 모두 보기",
payloads_add_repo_hint: "owner/name(예: EchoStretch/kstuff-lite)이나 전체 저장소 URL을 붙여 넣으세요. 릴리스는 선별 목록과 같은 방식으로 가져오며, 다운로드 시 동일한 ELF/zip 검사가 적용됩니다. 신뢰하는 저장소만 추가하세요. ps5upload는 사용자 저장소의 내용을 검증하지 않습니다.",
