"pkglib.addon.dlc": "DLC",
"pkglib.addon.update": "업데이트",
"pkglib.baseMissing.body": "이 {kind}은(는) {id}용이지만 본편 게임이 PS5에 설치되어 있지 않습니다. 소니 설치 프로그램은 이를 받아들이지만, 본편이 콘솔에 없으면 아무것도 설치되지 않습니다. 본편을 먼저 설치하세요.",
"pkglib.baseMissing.bodyPs5": "이 {kind}은(는) {id}용이지만 기본 게임이 PS5에 설치되어 있지 않습니다. 일부 PS5 업데이트는 앱 전체를 담고 있어 단독으로 설치됩니다. 이 업데이트가 안 되면 PS5가 알려 줍니다.",
