"pkglib.auth.retail.title": "리테일 서명 패키지입니다. 설치해도 라이선스가 부여되지 않으며, 실행하려면 콘솔에 유효한 권한이 필요합니다.",
"pkglib.auth.retail": "리테일",
"connection_prior_killed": "이전 헬퍼가 정상적으로 종료되지 않았습니다",
"connection_prior_killed_detail": "콘솔의 다른 페이로드가 종료했거나, 시스템 메모리가 부족했거나, 충돌했을 수 있습니다. 버그 보고서의 stderr.log에서 원인을 확인할 수 있습니다. 자동 로더로 ps5upload를 불러온다면 여기에서 전송해 보세요.",
