"pkglib.badge.pkgWarning": "패키지 확인",
"pkglib.fpkgsupport.title": "가짜 패키지(FPKG)를 설치하나요?",
"pkglib.fpkgsupport.lead": "PS5 가짜 패키지는 콘솔에 가짜 패키지 지원이 이미 로드되어 있어야 설치됩니다. 설치 전에 세 가지를 이 순서대로 모두 로드하세요:",
