"pkglib.fpkgsupport.smp": "— 설치된 타이틀을 등록하는 마운트 계층",
"pkglib.fpkgsupport.tail": "이것들이 없으면 콘솔이 설치를 거부하거나, 설치한 뒤 게임을 마운트하지 못합니다. 정품 및 디버그 패키지에는 필요 없습니다. 그런 패키지를 설치한다면 이 안내는 무시하세요.",
