"fpkg.about": "게임 폴더나 .exfat 또는 .ffpkg 마운트 이미지를 지정하세요. 변환기가 트리를 읽고, 실행 가능한 패키지에 필요한 것이 모두 있는지 확인한 뒤, 디버그 형식의 .pkg를 출력 폴더에 기록합니다.",
"fpkg.aboutWhere": "변환은 콘솔이 아니라 엔진을 실행하는 기기(이 컴퓨터, Docker 호스트 또는 Android 기기)에서 실행됩니다. 패키지를 설치하기 전까지는 콘솔에 아무것도 전달되지 않습니다. 설치는 이 컴퓨터에서 스트림하거나 먼저 PS5에 업로드하는 방식으로 합니다.",
"fpkg.aboutSource": "원본은 이미 복호화된 게임 트리여야 합니다. 정품 설치본은 여기에서 풀 수 없으며, 그런 것을 골랐다면 아래 검사가 알려 줍니다.",
"fpkg.aboutChecks": "검사 항목",
