"backport_verify_unpatched_body": "eboot에 아직 원래 SDK 버전이 남아 있어, 어떤 라이브러리를 설치해도 이 펌웨어에서 실행되지 않습니다. 라이브러리 세트 문제가 아닙니다. 백포트를 다시 실행하세요. 계속 반복되면 SDK 패치가 적용되지 않는 것입니다.",
