"backport_verify_missing": "라이브러리가 더 필요합니다",
"backport_verify_missing_body": "설치된 어떤 라이브러리에도 없는 함수를 게임이 호출했습니다. 시도할 더 큰 세트가 {count}개 남았습니다.",
