installed_launch_smp_refused: "kstuff가 실행 중인데도 PS5가 이 게임의 시작을 거부했습니다 (0x80940033). ShadowMount+는 게임이 시작될 때 마운트하는데, 그 과정이 이루어지지 않았습니다. 실행 중인 게임을 닫고 Payloads에서 ShadowMount+를 다시 보낸 뒤 플레이를 누르세요.",
