volumes_pkg_copies_hint: "이 선택이 하는 일: ‘업로드 후 설치’는 먼저 .pkg 파일을 PS5에 복사한 다음 그 사본으로 설치합니다. 여기서는 그 사본을 둘 드라이브만 정합니다. 게임이 설치되는 위치는 바뀌지 않으며(PS5의 저장공간 설정에서 정해짐), ‘스트림 후 설치’는 사본을 전혀 남기지 않습니다. 선택한 드라이브가 연결되어 있지 않으면 사본은 내장 저장공간에 저장됩니다.",
