captures: "스크린샷 및 클립",
captures_title: "캡처",
"arcpkg.choose": "압축 파일 선택…",
"arcpkg.help": "어느 폴더에든 .pkg 파일이 하나 이상 들어 있는 .zip, .7z, .rar에 사용합니다. 패키지만 PS5로 바로 풀고(이 컴퓨터에는 아무것도 풀지 않습니다), 게임 본편, 업데이트, DLC 순으로 하나씩 설치합니다. 분할 RAR(.part1.rar, .part2.rar…)도 지원합니다. 첫 번째 파트를 선택하고 나머지는 같은 위치에 두세요. RAR에 암호가 필요하면 입력을 요청합니다. 암호가 걸린 ZIP과 7z는 지원하지 않습니다.",
"arcpkg.keepsRunning": "다른 화면을 열어도 계속 실행되며 '작업'에서도 볼 수 있습니다.",
"arcpkg.notArchive": "이 파일은 .zip, .7z, .rar 압축 파일이 아닙니다.",
"arcpkg.pick": "압축 파일을 선택하세요",
"arcpkg.title": "압축 파일에서 패키지 설치",
"install.library.title": "PS5에 있는 패키지 사본",
"install.stream.file.help": ".pkg 또는 .fpkg를 선택하거나 이 창 아무 곳에나 끌어다 놓으세요. 설치가 끝날 때까지 앱을 열어 두세요. 진행 상황은 위의 대기열과 '작업'에 표시됩니다.",
"install.stream.file.title": "패키지 파일 설치",
"install.tab.stream.lead": "PS5가 이 컴퓨터나 링크에서 바로 설치합니다. PS5에 사본을 먼저 두지 않으므로 그쪽 여유 공간이 필요 없고, 가장 안정적인 설치 방법입니다.",
"install.tab.upload.lead": "패키지를 먼저 PS5로 복사한 다음 그 사본으로 설치합니다. PS5가 이 컴퓨터에 연결할 수 없을 때(스트림이 네트워크 오류로 실패할 때)나, 패키지를 PS5에 보관해 두고 나중에 이 컴퓨터 없이 다시 설치하려 할 때 사용하세요.",
"install.upload.file.browser": "여기서 패키지를 PS5로 복사하려면 데스크톱 앱이 필요합니다. 웹 UI에서는 '스트림 및 설치'를 사용하거나, 아래에서 이미 PS5에 있는 패키지를 설치하세요.",
"install.upload.file.help": ".pkg 또는 .fpkg를 선택하세요. 사본에는 PS5에 패키지 전체만큼의 여유 공간이 필요하며, 삭제할 때까지 아래 목록에 남습니다.",
"install.upload.file.title": "패키지를 PS5로 복사하고 설치",
"linkcard.confirm.direct": "PS5가 링크에서 패키지를 직접 내려받아 설치합니다. 시작한 뒤에는 이 컴퓨터가 필요 없고, 진행 상황은 여기가 아니라 PS5(다운로드)에 표시됩니다. PS5가 링크에 접근할 수 없으면 앱이 대신 이 컴퓨터를 거쳐 전달합니다. 이미 설치된 게임 위에 다시 설치하면 Sony 설치 프로그램이 실패할 경우 그 게임이 삭제될 수 있습니다. 신뢰할 수 있고 설치할 권리가 있는 패키지 링크만 사용하세요.",
"linkcard.confirm.download": "이 컴퓨터가 먼저 패키지 전체를 디스크에 저장한 다음 PS5에 설치합니다. 두 단계가 모두 끝날 때까지 켜져 있어야 하며 패키지만큼의 여유 공간이 필요합니다. 이미 설치된 게임 위에 다시 설치하면 Sony 설치 프로그램이 실패할 경우 그 게임이 삭제될 수 있습니다. 신뢰할 수 있고 설치할 권리가 있는 패키지 링크만 사용하세요.",
"linkcard.confirm.stream": "이 컴퓨터가 패키지를 내려받으면서 바로 PS5로 넘겨주므로, 설치가 끝날 때까지 켜져 있고 연결되어 있어야 합니다. 디스크에는 아무것도 저장되지 않습니다. 이미 설치된 게임 위에 다시 설치하면 Sony 설치 프로그램이 실패할 경우 그 게임이 삭제될 수 있습니다. 신뢰할 수 있고 설치할 권리가 있는 패키지 링크만 사용하세요.",
"linkcard.confirm.title": "이 링크에서 설치할까요?",
