stop: "중지",
activity_description_v2: "앱이 콘솔에서 하고 있거나 했던 모든 작업입니다. 업로드, 다운로드, 설치, 파일 작업이 포함됩니다. 여기서 무엇이든 중지하거나 다시 시도할 수 있습니다. 최근 100개가 재시작 후에도 유지됩니다.",
