health_subtitle_v2: "PS5, 이 앱, 그 사이의 네트워크가 제대로 동작하는지 확인하고, 문제가 있으면 무엇을 고쳐야 하는지 알려 주며, 둘 사이의 파일 전송 속도를 측정합니다.",
