shell_description_v2: "PS5의 헬퍼 프로세스 안에서 실행되는 명령을 입력합니다. 고급 사용자용입니다. 출력은 명령당 256KB로 제한되며, 위아래 화살표로 이전 명령을 불러옵니다.",
