"fpkg.image.folderOnly_v4": "게임 폴더, 게임 이미지 또는 게임이 들어 있는 압축 파일(.zip, .7z, .rar)만 게임 이미지로 만들 수 있습니다. 압축 파일은 먼저 출력 폴더에 풀립니다.",
