"fpkg.make.pkg_title": "패키지(.pkg)",
"fpkg.make.pkg_body": "스토어 게임처럼 PS5에 설치됩니다. 여기서 스트리밍하거나 먼저 업로드합니다. PS4 게임은 모든 펌웨어에서, PS5 게임은 11.60 이하에서 실행됩니다.",
"fpkg.make.image_title": "게임 이미지",
"fpkg.make.image_body": "PS5 드라이브에 두는 파일 하나로, ShadowMount+가 마운트해 홈 화면에 표시합니다. 아무것도 설치되지 않으며 PS5 패키지가 실행되지 않는 펌웨어에서도 실행됩니다.",
