"fpkg.make.why_image": "이 PS5 게임은 패키지로 설치되지만 FW {fw}에서 실행되지 않습니다. 이미지로는 실행됩니다.",
"fpkg.make.why_pkg": "패키지가 일반적인 선택입니다. 다른 게임처럼 설치되고 실행됩니다.",
