"fpkg.run.what_pkg": "패키지(.pkg)",
connection_payload_engine_unreachable: "앱이 이 컴퓨터에 있는 자신의 엔진에 연결하지 못해서 헬퍼가 PS5에서 시작됐는지 알 수 없습니다. PS5 문제가 아닙니다. 창 위쪽 알림에 이유가 나오고 엔진을 다시 시작할 수 있습니다. 그런 다음 '헬퍼 보내기'를 다시 누르세요. ({error})",
"engine_problem.missing.fix": "백신의 격리 항목에서 ps5upload-engine을 복원(또는 허용)하거나 앱을 다시 설치하세요.",
"engine_problem.missing.why": "앱 폴더에 엔진 프로그램이 없습니다. 보안 소프트웨어가 격리하는 경우가 있습니다.",
"engine_problem.port.fix": "'엔진 다시 시작'을 누르세요. 그래도 안 되면 방화벽이나 백신에서 ps5upload-engine을 허용한 뒤 앱을 다시 시작하세요.",
"engine_problem.port.why": "무언가가 엔진의 주소({url})를 차지하고 있지만 응답하지 않습니다. 그 포트를 쓰는 다른 프로그램이거나 연결을 막는 보안 소프트웨어입니다.",
"engine_problem.proxy.fix": "로컬 주소(127.0.0.1)에 대해 프록시나 VPN 도구를 끄거나, http_proxy / ALL_PROXY 설정 없이 앱을 시작하세요.",
"engine_problem.proxy.why": "엔진으로 가야 할 요청이 이 컴퓨터에 설정된 프록시로 갔습니다.",
"engine_problem.remote.fix": "엔진(Docker 컨테이너 또는 다른 컴퓨터)이 실행 중이고 그 주소로 접속되는지 확인하거나, 설정에서 주소를 바꾸세요.",
"engine_problem.remote.why": "이 앱이 사용하도록 설정된 엔진({url})이 응답하지 않습니다.",
"engine_problem.restart": "엔진 다시 시작",
"engine_problem.slow.fix": "'엔진 다시 시작'을 누르세요. 로컬 연결을 필터링하는 방화벽이나 백신도 원인이 될 수 있습니다. ps5upload-engine을 허용하세요.",
"engine_problem.slow.why": "엔진은 실행 중이지만 응답하지 않습니다.",
"engine_problem.stopped.fix": "'엔진 다시 시작'을 누르세요. 다시 멈추면 '로그' 화면에서 이유를 볼 수 있습니다.",
"engine_problem.stopped.why": "엔진이 실행되고 있지 않습니다. 멈췄거나 시작되지 않았습니다.",
"engine_problem.title": "앱이 이 컴퓨터의 엔진에 연결할 수 없습니다",
"engine_problem.web.fix": "서버(Docker 컨테이너)가 실행 중인지 확인한 뒤 이 페이지를 새로 고치세요.",
"engine_problem.web.why": "이 페이지가 자신을 제공한 ps5upload 서버와의 연결을 잃었습니다.",
gate_engine_down_body_v2: "이 화면에는 앱의 엔진이 필요한데 엔진이 응답하지 않습니다. 창 위쪽 알림에 이유가 나오고 엔진을 다시 시작할 수 있습니다.",
"profile.np.body": "Sony에 접속하지 않고도 PS5가 로그인한 계정을 PlayStation Network에 로그인된 것으로 취급하게 합니다. 일부 콘솔 기능은 로그인된 계정에만 열리며, 리모트 플레이도 그중 하나입니다. earthonion의 np-fake-signin을 사용하며, 버튼을 누를 때 프로젝트 페이지에서 받아옵니다.",
"profile.np.confirm_title": "이 계정을 로그인시킬까요?",
"profile.np.failed": "로그인이 실행되지 않았습니다",
"profile.np.fetching": "np-fake-signin을 받는 중…",
"profile.np.sending": "PS5로 보내는 중…",
"profile.np.sent": "np-fake-signin {version}이(가) PS5에서 실행됐습니다. PS5를 다시 시작하면 끝납니다. 그 후 계정이 로그인된 것으로 표시되고 설정 > 시스템 > 리모트 플레이를 켤 수 있습니다.",
"profile.np.sign_in": "로그인",
"profile.np.state_loading": "계정을 읽는 중…",
"profile.np.state_no_slot": "위 계정 중 이름이 {user}인 것이 없어서 np-fake-signin이 중단됩니다. 계정 이름을 로그인한 사용자와 같게 하거나, 그 사용자용 계정을 활성화하세요.",
"profile.np.state_no_user": "PS5에 로그인한 사용자가 없습니다. 원하는 프로필로 로그인한 뒤 돌아오세요.",
"profile.np.state_not_activated": "{user}(계정 {slot})에 아직 계정 ID가 없습니다. 먼저 위 '계정'에서 활성화하세요.",
"profile.np.state_ready": "준비됨: {user}(계정 {slot})이(가) 활성화되어 있습니다.",
"profile.np.step_activate": "계정에는 계정 ID가 필요합니다. PSN에 연결된 계정에는 있습니다. 없다면 위 '계정'에서 활성화하세요(오프라인 활성화).",
"profile.np.step_run": "그 사용자로 PS5에 로그인한 상태에서 '로그인'을 누르세요. 한 번 실행되고 끝납니다.",
"profile.np.title": "PlayStation Network에 로그인(오프라인)",
