"pkg.sony_80b21104": "PS5가 이 패키지를 받아들이지 않았습니다 (0x80B21104). 다른 패키지는 이 콘솔에 설치된다면 이 파일이 문제입니다. 대개 이 콘솔 펌웨어가 이해하는 것보다 새 도구로 만든 최신 게임의 패키지이거나, 가짜 서명(FPKG) 빌드가 아닌 패키지입니다. 사용하는 펌웨어용 패키지(백포트)를 쓰거나, 설치 프로그램을 거치지 않는 방법으로 설치하세요: 게임 폴더나 ShadowMount+용 게임 이미지(.exfat 또는 .ffpfsc)를 업로드로 복사합니다.",
