about_feat_convert_title: "게임 변환",
about_feat_install_body: "PS4 .pkg와 PS5 가짜 패키지(본편, 업데이트, DLC)를 이 컴퓨터, NAS 공유, USB 드라이브 또는 링크에서 설치합니다. PS5가 한 경로를 거부하면 앱이 다른 경로를 제안합니다.",
