activity_view_history: "기록",
"always_overwrite_hint_v2": "업로드 대상에 이미 파일이 있으면 확인을 건너뜁니다. 꺼 두면 덮어쓰기 / 이어하기 / 취소 확인이 표시됩니다.",
audit_empty_v2: "아직 기록된 것이 없습니다. 전원 작업(깨우기, 휴식 모드, 재시작, 종료), 삭제, 등록 해제, 제거, 설치를 하면 여기에 표시됩니다.",
audit_log_description_v3: "전원 작업, 삭제, 등록 해제, 제거, 설치의 기록으로, 이 컴퓨터의 이 앱 안에 보관됩니다. 최신 256개가 유지되고 오래된 것은 밀려납니다. 지우기 버튼은 없지만 앱 데이터나 브라우저 저장소를 지우면 삭제됩니다. 최근 100개가 표시됩니다.",
autoloader_title_v2: "연결 시 플레이리스트",
