backup_explain_v2: "파일을 본체 자체 저장소의 스냅샷으로 복사해 나중에 되돌릴 수 있게 합니다. 아래의 자주 쓰는 항목을 고르거나 직접 경로를 입력하세요.",
backup_limit_depth: "선택한 폴더보다 {n}단계 넘게 아래에 있는 폴더는 건너뜁니다.",
backup_limit_flatten: "파일은 경로의 모든 /를 _로 바꾼 이름으로 저장되므로, 서로 다른 두 경로가 같은 이름이 될 수 있고(a/b_c와 a_b/c) 그중 하나만 남습니다.",
backup_limit_keep: "이름별로 최신 스냅샷 {n}개만 유지됩니다. 새로 만들면 가장 오래된 것이 삭제됩니다.",
backup_subtitle_v3: "파일과 폴더를 PS5 자체에 보관되는 스냅샷으로 복사하고 나중에 되돌립니다. 이 컴퓨터로는 아무것도 복사되지 않습니다. 게임 저장 데이터는 저장 데이터를 사용하세요.",
bandwidth_cap_clear: "제한 해제",
bandwidth_cap_on_hint_v2: "다음에 시작하는 업로드부터 모든 업로드를 합쳐 약 {n} MB/s로 제한합니다. 0으로 설정하면 제한이 해제됩니다.",
beta_features_hint_v2: "개발 중인 화면이 있으면 사이드바에 추가합니다. 사용할 수는 있지만 아직 안정적이지 않으며, 변경되거나 제거될 수 있습니다.",
bringup_desc_v2: "페이로드에서 플레이리스트를 설정한 뒤 부팅할 때마다 사용합니다: 구동 플레이리스트(kstuff, ShadowMount+…)를 실행하고, 2단계와 같은 방식으로 헬퍼를 보낸 다음, 자동 로더 플레이리스트를 실행합니다.",
changelog_description_v2: "이 버전까지의 모든 ps5upload 버전에 대한 릴리스 노트로, 앱에 포함되어 있습니다. 더 새로운 릴리스와 다운로드는 GitHub에 있습니다.",
cheats_reapply: "실행 중인 게임에 다시 적용",
cheats_reapply_hint: "PS5의 치트 파일을 다시 읽고 켜져 있는 치트를 다시 적용합니다. 본체가 TV에 알림을 표시합니다.",
cheats_search_hint_v2: "게임 이름이나 타이틀 ID(예: PPSA07631 또는 CUSA00900)를 입력하고 검색을 누르세요",
