sendpayload_probe_invalid_ext: "페이로드는 .elf, .bin, .js, .lua 또는 .jar 파일이어야 합니다.",
sendpayload_probe_no_signature: "PS5Upload 서명이 없습니다 — 신뢰하는 페이로드일 때만 사용하세요.",
sendpayload_probe_ok: "페이로드 파일이 정상으로 보입니다.",
sendpayload_probe_read_error: "이 파일을 읽을 수 없습니다({error}). 파일이 아직 있고 열 수 있는지 확인한 뒤 다시 선택하세요.",
sendpayload_probe_too_small: "이 파일은 비어 있어 보낼 것이 없습니다.",
servers_subtitle: "NAS와 서버(SMB, FTP, FTPS, SFTP/WebDAV)입니다. 게임이나 파일을 찾아볼 때 어디서든 찾아보기 옆의 ▾에서 고를 수 있습니다.",
settings_artwork_cache_explain_v2: "게임 표지는 엔진이 실행되는 곳(이 컴퓨터, 웹 버전은 서버)에 보관되어 매번 PS5에서 읽는 대신 즉시 표시됩니다. 자동으로 새로 고쳐지며, 본체에서 게임을 설치하거나 제거하면 해당 본체의 표지가 삭제됩니다.",
settings_backup_downloaded: "{name} 다운로드됨",
settings_backup_hint_v2: "테마, PS5 목록, 알림 기록, 활동 로그 및 기타 설정을 하나의 JSON 파일로 묶어 앱 저장소를 지운 뒤나 다른 기기에서 복원할 수 있습니다. 본체 페어링, 컬렉션, 저장된 서버 비밀번호, 백포트 라이브러리는 포함되지 않습니다.",
settings_backup_restored: "설정 {count}개를 복원했습니다. 모든 변경을 적용하려면 앱을 다시 시작하세요.",
settings_backup_saved: "{path}에 저장됨",
settings_card_console_rest: "휴식 모드",
settings_card_console_connect: "연결",
auto_bringup_label: "자동으로 구동",
auto_bringup_hint: "저장된 PS5의 로더(elfldr, 포트 9021)가 켜져 있고 헬퍼가 실행 중이 아니면, 앱이 빠른 구동을 스스로 실행합니다: 설정했다면 구동 플레이리스트, 그다음 헬퍼, 그다음 자동 로더 플레이리스트. 콘솔이 시작될 때마다 한 번이며, 휴식 모드 후에는 헬퍼만 다시 보냅니다. 콘솔 자체의 오토로더가 먼저 끝나도록 로더가 나타난 뒤 약 90초를 기다립니다. 기본값은 꺼짐입니다.",
bringup_auto_hint_short: "PS5의 로더가 켜져 있고 헬퍼가 꺼져 있으면, 로더가 나타난 뒤 약 90초 후에 스스로 실행합니다. 콘솔이 시작될 때마다 한 번입니다.",
settings_card_install_fallback: "PS5가 패키지를 가져올 수 없을 때",
settings_card_system_files: "시스템 파일",
settings_file_hint_v2: "주요 설정(테마, 언어, 엔진, 저장 경로, 업로드 기본값, 접근성, 사이드바)은 이 JSON 파일에 반영됩니다. 직접 편집할 수 있으며, 다음에 앱을 실행할 때 적용됩니다. 모든 것이 들어 있지는 않으므로, 모든 설정을 옮기려면 백업 / 복원을 사용하세요.",
settings_group_console: "본체",
settings_group_fakelibs: "백포트",
settings_group_files_saves: "파일 및 저장 데이터",
settings_group_installs: "설치",
settings_schedule_label_placeholder_v2: "레이블(예: 저장 데이터 백업)",
settings_updates_browser_note: "이 웹 페이지는 ps5upload 엔진이 제공하며 엔진과 함께 업데이트됩니다: 새 Docker 이미지를 받아(또는 서버의 엔진을 업데이트해) 다시 시작하세요.",
"show_file_list_hint_v2": "진행 막대 아래에 업로드 중인 파일 목록을 표시합니다. 파일이 수천 개인 폴더에서 목록이 번잡하면 끄세요. 전체 진행률, 속도, 남은 시간은 계속 보입니다.",
show_file_list_v2: "업로드 중 파일 목록 표시",
stats_description_v2: "이 본체에 대해 표시된 작업의 합계입니다. 앱은 최근 {count}개를 보관하므로 그보다 오래된 것은 집계되지 않습니다. 로컬 기록으로 계산하며, 아무것도 이 기기 밖으로 나가지 않습니다.",
status_keep_awake_tooltip_v2: "깨우기 유지가 “연결 중 항상”으로 설정되어 있습니다 — 앱이 열려 있는 동안 연결된 본체는 자동으로 휴식 모드에 들어가지 않습니다. 설정 → 본체에서 변경하세요.",
update_idle_v2: "아직 확인하지 않았습니다. 자동 확인이 켜져 있으면 앱이 실행될 때 백그라운드에서 확인합니다(하루에 최대 한 번).",
upload_auto_resume_hint_browser: "업로드가 전송 중에 끊기면 PS5의 헬퍼가 다시 응답할 때 중단된 지점부터 이어서 하며, 몇 번 다시 시도한 뒤 포기합니다. 이 페이지는 헬퍼 자체를 다시 보낼 수 없으므로, PS5가 재시작되었다면 먼저 헬퍼를 다시 보내세요. PS5 공간 부족 같은 치명적인 문제는 바로 중지됩니다. 기본적으로 켜져 있습니다.",
upload_wake_for_uploads: "대기 중인 업로드를 위해 PS5 깨우기",
upload_wake_for_uploads_hint: "업로드가 휴식 모드의 PS5를 기다리면 깨우기 신호를 보내고, 헬퍼가 다시 실행되면 이어서 진행합니다. 연결 화면에서 깨우기를 설정한 콘솔에만 적용됩니다. 기본값은 켜짐입니다.",
upload_picker_from_ps5_hint: "다른 PS5에서 복사하나요? 파일 시스템에서 파일을 선택하고 다른 본체로 보내기를 고르세요.",
usb_wizard_title_v2: "USB 페이로드 스틱",
v5_qa_ready: "준비됨",
v5_qa_unavailable: "사용할 수 없음",
"fpkg.stage.pack": "LZ4 에셋 패킹",
"fpkg.image.lz4": "AMPR LZ4 에셋 팩 (더 작음, ShadowMount+용)",
