"fpkg.image.lz4_no_ampr": "이 게임은 AMPR로 파일을 읽지 않으므로 에셋 팩을 제공할 것이 없습니다. 대신 .ffpfsc로 압축하세요. ShadowMount+가 모든 게임에서 압축을 풉니다.",
