"pkg.reason.staged_refused": "PS5가 자체 저장소에서 이 패키지를 거부했습니다. 6.3.1 이전에는 ps5upload의 버그 때문에 발생했으나 수정되었으므로 더 이상 일어나지 않아야 합니다. 파일 문제는 아닙니다. 다시 발생하면 컴퓨터(데스크톱 앱 또는 홈 서버의 웹 UI)에서 스트림 및 설치로 설치하고 버그 보고서를 보내 주세요.",
