"ps4move_no_users": "이 PS4에는 세이브가 있는 사용자가 없습니다.",
"ps4move_user": "PS4 사용자(폴더)",
"ps4move_user_row": "{id} · 게임 {n}개",
"ps4move_reading_games": "이 사용자의 세이브를 읽는 중…",
"ps4move_backup": "{n}개를 이 컴퓨터로 복사",
"ps4move_copying": "세이브를 이 컴퓨터로 복사하는 중…",
"ps4move_copying_one": "{title}을(를) 이 컴퓨터로 복사하는 중…",
"ps4move_step3": "3. 이 PS5로",
"ps4move_ps5_user": "PS5 사용자",
"ps4move_ps5_account": "이 사용자의 계정 ID: {id}",
"ps4move_account_hint": "세이브는 계정 ID를 따릅니다. PS4 계정의 ID가 이 사용자의 ID여야 합니다. 아니라면 계속하기 전에 계정에서 설정하세요(이 사용자가 열 수 있는 세이브가 바뀝니다).",
"ps4move_ps4_account": "PS4 계정의 ID(선택, 확인용)",
"ps4move_mismatch": "ID가 다릅니다. PS4의 세이브가 이 사용자에서는 열리지 않습니다. 먼저 계정에서 이 사용자에게 PS4 계정의 ID를 주거나 다른 사용자를 고르세요.",
"ps4move_checked": "이 PS5 사용자가 PS4 계정의 ID를 가졌는지 확인했습니다",
"ps4move_match": "ID가 일치합니다.",
"ps4move_done": "완료",
"ps4move_ready": "준비됨",
"ps4move_not_ready": "아직 이 사용자에게 없습니다. PS5에서 게임을 한 번 실행해 저장한 뒤 다시 확인을 누르세요.",
"ps4move_recheck": "다시 확인",
"ps4move_put_n": "{n}개를 PS5에 넣기",
"ps4move_confirm_title": "PS4 세이브 {n}개를 이 PS5에 넣을까요?",
"ps4move_confirm_body": "이 PS5 사용자의 각 게임 세이브를 백업한 뒤 PS4의 것으로 바꿉니다. 게임은 닫혀 있어야 합니다. PS5 세이브는 백업(\"PS4 세이브 전\" 표시)에서 되돌릴 수 있습니다.",
"ps4move_put": "PS5에 넣기",
"save_backup_before_ps4": "PS4 세이브 전",
"accounts_backup_title": "사용자 정보 백업",
"accounts_backup_description": "이 PS5의 모든 사용자를 담은 텍스트 파일을 내려받습니다: 이름, 사용자 및 계정 ID, 각 계정의 활성화와 로그인 상태, 초기화나 충돌 후 새 사용자에게 예전 계정 ID를 주는 방법(세이브는 계정 ID를 따릅니다). 비공개로 보관하세요.",
"accounts_backup_button": "사용자 정보 다운로드(.txt)",
