"rp_running_elsewhere": "플레이가 {name}에서 실행 중입니다",
"rp_show_here": "여기에 표시",
"rp_running_elsewhere_body": "다른 창에서 또는 이 페이지를 새로고침하기 전에 시작되었으며 아직 진행 중입니다.",
"rpg_user_title": "PS5에서 사용자로 로그인하기",
"rpg_user_body": "본체에서 플레이할 사용자를 고르세요. 화면 앞에 있을 필요는 없지만, 사용자는 로그인되어 있어야 합니다. 로그인 암호가 없는 사용자를 쓰세요. 암호가 있으면 본체가 켜질 때 자동 로그인이 멈춥니다.",
"rpg_account_title": "그 사용자에게 계정 ID 부여하기",
"rpg_account_body": "리모트 플레이는 계정 ID로 페어링합니다. PlayStation Network에 연결된 사용자에게는 이미 있습니다. 오프라인 사용자는 위 '사용자'에서 설정해야 합니다(어떤 ID든 됩니다. 적어 두세요. 이후 만드는 세이브 데이터가 그 ID에 묶입니다).",
"rpg_signin_title": "계정을 PlayStation Network에 로그인하기(오프라인)",
"rpg_signin_body": "PS5는 로그인된 계정만 리모트 플레이를 쓰게 합니다. 본체의 리모트 플레이 설정이 회색이면 아래 오프라인 로그인을 실행한 뒤(Sony로는 아무것도 보내지 않습니다) PS5를 다시 시작하세요. 되돌릴 수 있습니다.",
"rpg_signin_fix": "로그인으로 이동",
"rpg_service_title": "리모트 플레이 켜기",
"rpg_service_body": "설정 › 시스템 › 리모트 플레이 › 리모트 플레이 활성화. 앱에서 대신 켤 수 있으며, 펌웨어 10.00 이상에서는 이 사용자에게도 허용할 수 있습니다. 그 후 시작에서 리모트 플레이가 꺼져 있다고 나오면 PS5 자체 설정에서 켜세요. 본체의 스위치가 기준입니다.",
"rpg_rest_title": "휴식 모드에서 PS5를 켤 수 있게 하기",
"rpg_rest_body": "설정 › 시스템 › 절전 › 휴식 모드에서 사용 가능한 기능에서 '인터넷에 연결 유지'와 '네트워크로 PS5 켜기 활성화'를 켜세요. 이 둘이 꺼져 있으면 휴식 모드인 본체를 켤 수 없고 몇 초 뒤 네트워크도 절전 상태가 됩니다. 이 항목은 본체에서만 확인할 수 있습니다.",
"rpg_pair_title": "이 앱을 본체와 페어링하기",
"rpg_pair_body": "연결 › 켜고 로그인 › 설정. 한 번의 클릭으로 이 앱을 PS5에 등록하고(PS Remote Play 앱 페어링과 같습니다) 키를 이 컴퓨터에 보관합니다. 스트리밍, 켜기, 로그인 모두 이 키를 씁니다. 본체를 초기화하거나 사용자를 바꾼 뒤에는 다시 하세요.",
"rpg_play_title": "플레이",
"rpg_play_body": "리모트 플레이를 열고 시작을 누르세요. 본체가 휴식 모드이면 켜고, 로그인한 뒤 스트리밍합니다. 이 컴퓨터에 연결한 컨트롤러, 키보드 또는 터치로 플레이하세요. Sony의 PS Remote Play 앱이나 chiaki-ng를 쓰려면 아래에서 PIN을 요청해 그곳에 입력하세요.",
"rpg_play_fix": "리모트 플레이 열기",
"rpg_title": "리모트 플레이 설정",
"rpg_progress": "확인된 단계 {n}개 중 {done}개 완료",
"rpg_on_console": "본체에서 확인",
"rpg_trouble": "그래도 안 된다면",
"rpg_t_start_q": "플레이 화면에서 시작이 회색으로 비활성화되어 있습니다.",
"rpg_t_start_a": "이 앱이 아직 그 본체와 페어링되지 않았습니다. 6단계(연결 › 켜고 로그인 › 설정)를 하세요.",
"rpg_t_pair_q": "페어링을 설정하면 활성화된 계정으로 로그인한 사용자가 없다고 나옵니다.",
"rpg_t_pair_a": "1, 2단계: PS5에서 사용자로 로그인하고 계정 ID를 부여한 뒤 다시 시도하세요.",
"rpg_t_grey_q": "PS5 자체의 리모트 플레이 설정이 회색으로 표시됩니다.",
"rpg_t_grey_a": "계정이 PlayStation Network에 로그인되어 있지 않습니다. 오프라인 로그인(3단계)을 실행하고 PS5를 다시 시작하세요.",
"rpg_t_wake_q": "본체가 켜지지 않거나, 켜져도 사용자 화면에 머뭅니다.",
"rpg_t_wake_a": "본체에서 5단계를 확인하세요. 로그인 암호가 있는 사용자는 자동 로그인을 막습니다. 본체를 초기화했거나 사용자가 바뀌었다면 페어링을 다시 설정하세요(6단계).",
"rpg_t_black_q": "화면이 검은 채로 있거나, 끊기거나, 소리가 지직거립니다.",
"rpg_t_black_a": "PS5와 이 컴퓨터를 유선 연결이나 5 GHz Wi-Fi로 연결하고, 리모트 플레이 설정에서 720p나 30 fps를 시도하세요. 이 컴퓨터의 방화벽이 로컬 네트워크에서 앱을 허용해야 합니다(리모트 플레이는 TCP 및 UDP 포트 9295–9304를 씁니다). 브라우저에서는 최신 Chrome, Edge 또는 Safari를 쓰세요. 화면 표시에 WebCodecs가 필요합니다.",
"rpg_t_busy_q": "PS5가 아직 지난 세션을 마무리 중이라거나, 다른 본체가 스트리밍 중이라고 나옵니다.",
"rpg_t_busy_a": "한 번에 한 본체만 스트리밍하며, 세션이 끝난 뒤 PS5에는 최대 30초가 걸립니다. 다른 스트림을 멈추고 잠시 기다린 뒤 다시 시작을 누르세요.",
"rpg_t_restrict_q": "오프라인 로그인 후 게임이 콘솔 제한을 해제하라고 요구합니다.",
"rpg_t_restrict_a": "이 페이지의 로그인 되돌리기를 쓰고 다시 시작하거나, 설정 › 가족 및 자녀 보호 기능 › PS5 콘솔 제한에서 제한을 풀어 주세요(바꾸지 않았다면 패스코드 0000).",
