"rp_other_device_playing_body": "PS5는 한 번에 한 기기와만 리모트 플레이를 합니다. 여기서 시작하면 그쪽은 종료됩니다.",
"mesh_rp_started": "{name}이(가) 이 콘솔에서 플레이를 시작했습니다",
"rp_keys_body3": "화면을 클릭하면 키보드로 플레이합니다. Esc를 누르면 포인터가 돌아옵니다. 더블 클릭하면 전체 화면이며, 전체 화면에서는 Esc를 짧게 누르면 ○, 길게 누르면 전체 화면을 종료합니다. 키, 소리 등은 설정에 있습니다.",
"rp_play_description2": "PS5를 이 앱으로 스트리밍해 컨트롤러, 키보드 또는 터치로 플레이하세요. 휴식 모드의 콘솔을 자동으로 깨우며, 다른 화면을 사용하는 동안에도 플레이가 계속됩니다.",
"rp_banner_moved": "{name}의 플레이가 다른 창에 표시 중입니다",
