"dump_decrypt_risk": "복호화하면 콘솔이 멈출 수 있습니다",
"dump_decrypt_risk_body": "복호화를 위해 헬퍼는 실행 파일마다 모든 프로그램이 쓰는 시스템 일부를 잠깐 교체합니다. 그 순간 게임이 파일을 읽으면 콘솔이 멈춰 강제로 전원을 꺼야 할 수 있습니다. 진행 중에는 게임 시작 화면에 머물러 주세요. 펌웨어 13.60 이하만 지원하며, 그보다 새 펌웨어에서는 덤프가 단순 복사입니다.",
