"send_title_v2": "업로드 및 설치",
"collection.send_many_body_v2": "각 PS5는 없는 것을 받습니다. 게임 패키지 또는 폴더·이미지·압축 파일, 그리고 가진 게임의 최신 업데이트와 DLC입니다. 패키지는 이 컴퓨터에서 스트리밍되고, 나머지는 '업로드 및 설치'에서 정한 드라이브의 homebrew 폴더로 업로드됩니다.",
"first_run_step4_body_v3": ".ffpkg 게임 이미지가 담긴 USB 메모리를 PS5에 꽂으면 ShadowMount+가 자동으로 마운트하며 게임에 표시됩니다. 다른 파일을 보내거나 .pkg 패키지를 설치하려면 '업로드 및 설치'를 사용하세요.",
"first_run_go_upload_v2": "업로드 및 설치 열기",
"fpkg.aboutFake_v2": "결과물은 가짜 패키지이므로, 설치 전에 콘솔에 가짜 패키지 지원을 로드해야 합니다: kstuff(PS5 가짜 패키지 지원 빌드), a53_ppr_install_fast.elf, shadowmountplus.elf를 이 순서대로. '업로드 및 설치' 화면의 설치 버튼 옆에도 같은 내용이 있습니다.",
"fpkg.openUpload_v2": "업로드 및 설치 열기",
"connection_step3_hint_v3": "'업로드 및 설치'를 열고 게임 폴더, .exfat 또는 .ffpkg 이미지, 또는 .pkg 패키지를 끌어다 놓으세요. 보낸 이미지와 폴더는 '게임'의 해당 게임 페이지에 표시되며, 마운트를 누르면 PS5 홈 화면에 나타납니다.",
"connection_go_upload_v2": "업로드 및 설치 열기",
"netdoctor.speed_cap.on.fix_v2": "필요 없으면 '업로드 및 설치'에서 제한을 해제하세요.",
"payloads_fpkg_ppr_note_v2": "가짜 패키지를 설치하려면 이 목록에 없는 a53_ppr_install_fast.elf도 필요합니다. 배포된 다운로드는 없으며 GitHub의 소스에서 빌드합니다. 가짜 패키지에 필요한 모든 것은 '업로드 및 설치' 화면에 순서대로 나와 있습니다.",
"fs_extract_next_pkgs_v2": "패키지 {n}개가 들어 있습니다. '업로드 및 설치'나 여기 각 행에서 설치하세요.",
"game_hub_no_addons_v2": "이 타이틀에 준비된 DLC 패키지가 없습니다. '업로드 및 설치'에서 보내세요.",
"game_hub_open_install_v2": "업로드 및 설치 열기",
"bandwidth_cap_off_hint_v3": "제한 없음. 업로드가 Wi-Fi/LAN을 가득 채워 다른 기기가 느려지면 설정하세요. 다음에 시작하는 것부터 '업로드 및 설치', 대기열, 파일에서의 모든 업로드에 적용됩니다.",
"queue_links_cleared_body_v2": "재시작 후 설치 링크 {n}개가 유지되지 않았습니다. 링크는 디스크에 저장되지 않습니다. '업로드 및 설치'에서 다시 추가하세요.",
"game_hub_no_updates_v2": "이 타이틀에 준비된 업데이트 패키지가 없습니다. '업로드 및 설치'에서 보내세요.",
"pkglib.fpkgsupport.firmware": "PS5 가짜 패키지(PS5 FPKG)는 11.60보다 새로운 펌웨어에서 아직 지원되지 않습니다. 설치는 되지만 게임이 시작되지 않습니다. PS4 가짜 패키지는 문제없습니다.",
"upload_drop_here3": "패키지, 게임, 디스크 이미지, 압축 파일 또는 아무 파일을 놓거나 선택하세요",
"upload_pick_here_mobile3": "패키지, 게임, 디스크 이미지, 압축 파일 또는 아무 파일을 선택하세요",
"upload_drop_kind_pkg": "패키지(.pkg, .fpkg): 게임, 업데이트 또는 DLC로 설치되며, 여기서 스트리밍하거나 먼저 업로드합니다.",
"upload_drop_kind_game": "게임 폴더와 게임 덤프: PS5로 복사되며 홈 화면에 둘 수 있습니다.",
"upload_drop_kind_image": "디스크 이미지(.exfat, .ffpkg, .ffpfs, .ffpfsc): PS5로 복사되며 마운트할 수 있습니다.",
"upload_drop_kind_archive": "압축 파일(.zip, .7z, .rar): PS5에 압축이 풀립니다.",
"upload_drop_kind_other": "그 밖의 파일이나 폴더: 그대로 복사됩니다.",
"upload_other_ways": "또는 패키지 설치:",
"queue_stream_fail_hint": "'스트림 및 설치'는 PS5가 이 컴퓨터에서 패키지를 가져오게 합니다. 계속 실패하면 PS5가 접근할 수 있도록 이 컴퓨터의 방화벽에서 로컬 네트워크의 ps5upload를 허용하거나, '업로드로 다시 시도'를 사용하세요. 이 방법은 패키지를 먼저 PS5에 복사한 뒤 설치합니다.",
"err_install_enoent_generic_v2": "Sony의 설치 프로그램이 설치 중 필요한 파일을 열 수 없었습니다(커널 오류 0x80020002 = ENOENT). DLC pkg라면 기본 게임이 아직 설치되지 않은 것입니다. 먼저 기본 게임을 설치하세요. 그렇지 않다면 업로드와 설치 사이에 스테이징된 패키지가 삭제되었을 수 있습니다. 설치를 한 번 다시 시도하세요. 계속 실패하면 '업로드 및 설치'에서 '스트림 및 설치'로 설치하세요. 패키지를 먼저 본체에 복사하지 않고 이 컴퓨터에서 바로 보냅니다.",
"upload_convert_first": "먼저 변환",
"batch_convert_first_hint": "체크한 게임, 폴더, 이미지를 작업실에서 열어 먼저 패키지, 이미지 또는 폴더로 만듭니다",
"add_sources_pick_folders": "폴더를 하나 이상 선택",
"add_sources_pick_files": "파일을 하나 이상 선택",
